@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

:root {
    --color-bg: #0f0f1a;
    --color-surface: #16161A;
    --color-accent: #00A868;
    --color-accent-light: #2FD48F;
    --color-ink: #07110C;
    --color-text: #EAE6E1;
    --color-muted: #8A8A94;
    --color-heading: #ffffff;
    --font-main: 'Inter', system-ui, sans-serif;
    --max-width: 1100px;
    --space-section: clamp(3rem, 8vw, 6rem);
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-main);
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: 1.6;
}

/* Skip link: off screen until it has focus */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-accent);
    color: var(--color-ink);
    padding: 0.5rem 1rem;
    z-index: 1000;
    transition: top 0.2s ease;
}

.skip-link:focus {
    top: 0;
}

/* Focus: replaced, never removed */
:focus-visible {
    outline: 2px solid var(--color-accent-light);
    outline-offset: 3px;
}

/* Header: a column on the phone, a row from 768 up */
.header {
    position: sticky;
    top: 0;
    z-index: 100;
    background-color: rgba(15, 15, 26, 0.95);
    backdrop-filter: blur(8px);
}

.header__nav {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.75rem;
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 1rem 1.5rem;
}

.header__brand {
    color: var(--color-accent-light);
    text-decoration: none;
    font-weight: 700;
    font-size: 1.25rem;
}

.header__links {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 1rem;
    list-style: none;
}

.header__link {
    color: var(--color-muted);
    text-decoration: none;
    font-size: 0.95rem;
    transition: color 0.2s ease;
}

.header__link:hover {
    color: var(--color-accent-light);
}

/* Hero: the entrance from 2.4 */
@keyframes fade-in-up {
    from {
        opacity: 0;
        transform: translateY(16px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.hero {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    min-height: 80vh;
    padding: 2rem 1.5rem;
}

.hero__title {
    font-size: clamp(2rem, 6vw, 3.6rem);
    color: var(--color-heading);
    margin-bottom: 1rem;
    animation: fade-in-up 0.8s ease forwards;
}

.hero__name {
    color: var(--color-accent-light);
}

.hero__subtitle {
    font-size: clamp(1rem, 2.5vw, 1.3rem);
    color: var(--color-muted);
    margin-bottom: 2rem;
    max-width: 600px;
    opacity: 0;
    animation: fade-in-up 0.8s ease 0.3s forwards;
}

.hero__cta,
.contact__cta {
    display: inline-block;
    background-color: var(--color-accent);
    color: var(--color-ink);
    padding: 0.9rem 2rem;
    border-radius: 6px;
    text-decoration: none;
    font-weight: 600;
    transition: background-color 0.2s ease, transform 0.2s ease;
}

.hero__cta:hover,
.contact__cta:hover {
    background-color: var(--color-accent-light);
    transform: translateY(-2px);
}

/* Sections share one width and one rhythm */
.skills,
.about,
.projects,
.contact {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: var(--space-section) 1.5rem;
}

.skills__heading,
.about__heading,
.projects__heading,
.contact__heading {
    text-align: center;
    font-size: clamp(1.5rem, 3vw, 2rem);
    color: var(--color-heading);
    margin-bottom: 2rem;
}

/* Skills: a grid that fits as many cards as the width allows */
.skills__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
    list-style: none;
}

.skill-card {
    background-color: var(--color-surface);
    padding: 2rem;
    border-radius: 8px;
    border-top: 3px solid var(--color-accent);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.skill-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(0, 168, 104, 0.15);
}

.skill-card__title {
    color: var(--color-accent-light);
    margin-bottom: 0.75rem;
}

/* About: stacked on the phone, side by side from 768 up */
.about__content {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 2rem;
}

.about__image {
    width: 200px;
    height: 200px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid var(--color-accent);
    flex-shrink: 0;
}

.about__text p + p {
    margin-top: 1rem;
}

/* Projects */
.projects__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
}

.project-card {
    background-color: var(--color-surface);
    padding: 2rem;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    transition: transform 0.3s ease;
}

.project-card:hover {
    transform: translateY(-4px);
}

.project-card__title {
    color: var(--color-heading);
}

.project-card__link {
    color: var(--color-accent-light);
    text-decoration: none;
    font-weight: 600;
    margin-top: auto;
    transition: color 0.2s ease;
}

.project-card__link:hover {
    color: var(--color-heading);
}

/* Contact */
.contact {
    text-align: center;
}

.contact__text {
    margin-bottom: 2rem;
    color: var(--color-muted);
}

/* Footer */
.footer {
    text-align: center;
    padding: 2rem 1.5rem;
    background-color: var(--color-surface);
    color: var(--color-muted);
    font-size: 0.9rem;
}

/* The wide layout, added on top of the phone */
@media (min-width: 768px) {
    .header__nav {
        flex-direction: row;
        justify-content: space-between;
    }

    .header__links {
        gap: 1.5rem;
    }

    .about__content {
        flex-direction: row;
        align-items: center;
        text-align: left;
    }
}

/* Reduced motion: complete, so nothing loops and nothing glides */
@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior: auto;
    }

    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

