function describeClass(playerClass, level) {
  const tier = level >= 30 ? 'veteran' : level >= 10 ? 'journeyman' : 'rookie';
  let stats;
  switch (playerClass) {
    case 'warrior': stats = { hp: 150, atk: 20, mp: 0 }; break;
