function protect(header, tokenSecret, now) {
  if (!header) return { status: 401, reason: 'missing' };
  const space = header.indexOf(' ');
  const scheme = space === -1 ? '' : header.slice(0, space);
  const raw = space === -1 ? '' : header.slice(space + 1).trim();
