function swearJoin(store, oath) {
  var key = oath.party + ':' + oath.member;
  if (store[key]) return { ok: false, code: 11000 };
  store[key] = { party: oath.party, member: oath.member, role: oath.role };
  return { ok: true, oath: store[key] };
}

