function upstreamPath(location, proxyPass, requestPath) {
  const match = proxyPass.match(/^https?:\/\/[^/]+(\/.*)?$/);
  const uri = match && match[1];
  if (!uri) return requestPath;
  return uri + requestPath.slice(location.length);
}
