}

function run(events) {
  let state = 'idle';
  let requests = 0;
  events.forEach(function (event) {
    const next = transition(state, event);
    if (event === 'send' || event === 'retry') {
      if (next !== state) requests += 1;
    }
    state = next;
  });
  return { state: state, requests: requests };
}

