function kthLargest(nums, k) {
  const h = [];
  const up = (i) => {
    while (i > 0 && h[i] < h[(i - 1) >> 1]) {
      const p = (i - 1) >> 1;
      [h[i], h[p]] = [h[p], h[i]];
      i = p;
    }
  };
  const down = (i) => {
    const l = 2 * i + 1, r = l + 1;
    let m = i;
    if (l < h.length && h[l] < h[m]) m = l;
    if (r < h.length && h[r] < h[m]) m = r;
    if (m === i) return;
    [h[i], h[m]] = [h[m], h[i]];
    down(m);
  };
