function plainGet(url) {
  return { status: 200, body: url };
}

function withLog(log, inner) {
  return function get(url) {
    log.push('in ' + url);
    const res = inner(url);
    log.push('out ' + res.status);
    return res;
  };
}

function withPrefix(prefix, inner) {
  return function get(url) {
    return inner(prefix + url);
  };
}

