function createDoc() {
  let body = '';
  const snaps = new WeakMap();
  return {
    edit(next) { body = next; },
    read() { return body; },
    save(label) {
      const token = { label };
      snaps.set(token, body);
      return token;
    },
    restore(token) {
      if (!snaps.has(token)) throw new Error('not a snapshot');
      body = snaps.get(token);
    },
  };
}

